#!/usr/bin/env node
// Verify relative links and image sources in the release docs changed for 0.4.0.
import { readFileSync, existsSync, statSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const ROOT = process.cwd();
const FILES = process.argv.slice(2);

// Generated by scripts/marketing/build.mjs; it never exists in the source tree.
const GENERATED = new Set(['assets/motion.js']);

if (FILES.length === 0) {
  console.error('usage: node scripts/check-doc-links.mjs <file> [...]');
  process.exit(2);
}

const MD_LINK = /!?\[[^\]]*\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g;
const HTML_ATTR = /(?:src|href)="([^"]+)"/g;

let failures = 0;
let checked = 0;

for (const rel of FILES) {
  const abs = resolve(ROOT, rel);
  const text = readFileSync(abs, 'utf8');
  const dir = dirname(abs);
  const found = new Set();
  for (const m of text.matchAll(MD_LINK)) found.add(m[1]);
  for (const m of text.matchAll(HTML_ATTR)) found.add(m[1]);

  for (const raw of found) {
    if (!raw) continue;
    if (/^(?:[a-z][a-z0-9+.-]*:|\/\/|#|\/)/i.test(raw)) continue;
    const target = decodeURIComponent(raw.split('#')[0].split('?')[0]);
    if (!target) continue;
    checked += 1;
    if (GENERATED.has(target)) continue;
    const path = resolve(dir, target);
    if (!path.startsWith(ROOT)) {
      console.error(`ESCAPE ${rel} -> ${raw}`);
      failures += 1;
      continue;
    }
    if (!existsSync(path)) {
      console.error(`MISSING ${rel} -> ${raw}`);
      failures += 1;
      continue;
    }
    if (statSync(path).isDirectory()) {
      console.error(`DIRECTORY ${rel} -> ${raw}`);
      failures += 1;
    }
  }
}

console.log(`checked ${checked} relative references in ${FILES.length} files, ${failures} problem(s)`);
process.exit(failures === 0 ? 0 : 1);
